import { Suspense } from 'react';
import { ProductList } from './ProductList';
import { revalidateTag } from 'next/cache';

export default function Page() {
  async function invalidateProductCache() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Product Listing with Cache Invalidation</h1>

      <Suspense fallback={<div>Loading products...</div>}>
        <ProductList />
      </Suspense>

      <form action={invalidateProductCache} style={{ marginTop: '2rem' }}>
        <button
          type="submit"
          style={{
            padding: '0.75rem 1.5rem',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '1rem'
          }}
        >
          Invalidate Product Cache
        </button>
      </form>

      <div style={{ marginTop: '2rem', padding: '1rem', backgroundColor: '#f5f5f5', borderRadius: '4px' }}>
        <h3>How it works:</h3>
        <ul>
          <li>The ProductList component uses 'use cache' directive to cache the product data</li>
          <li>Data is tagged with "products" cache tag for selective invalidation</li>
          <li>The timestamp shows when the data was cached</li>
          <li>Click the button to invalidate the cache and see fresh data on refresh</li>
        </ul>
      </div>
    </div>
  );
}

